import numpy as np
from scipy.optimize import minimize, Bounds
from scipy.spatial.distance import pdist, squareform
import os 

# --- Constants ---
N = 26
BASE_PACKING_PATH = 'storage/Scientia/nmap/n26/sota_nudged_375_data'

# --- Stage 1: Nudging Parameters ---
ALPHA_ENCOURAGE = 1e2
EPS_CLOSE = 0.005
ENCOURAGE_PAIRS = [(17, 24)] # Circles 18 and 25 -> indices 17 and 24

# --- Stage 2: Refinement Parameters ---
JITTER_AMPLITUDES = [1.0e-4, 5.0e-4, 1.0e-3, 2.0e-3]
RESTARTS_PER_AMPLITUDE = 5

# --- Helper functions ---
def pack_to_x(c, r):
    x = np.zeros(N * 3); x[0::3], x[1::3], x[2::3] = c[:,0], c[:,1], r; return x

def x_to_pack(x):
    c = x.reshape(N, 3)[:, :2]; r = x[2::3]; return c, r

# --- Objective Functions ---
def penalized_objective(x):
    c, r = x_to_pack(x)
    base_obj = -np.sum(r)
    penalty = 0.0
    for i, j in ENCOURAGE_PAIRS:
        dist = np.linalg.norm(c[i] - c[j])
        target_dist = r[i] + r[j] + EPS_CLOSE
        penalty += ALPHA_ENCOURAGE * max(0, dist - target_dist)**2
    return base_obj + penalty

def standard_objective(x):
    return -np.sum(x[2::3])

# --- Constraints ---
def constraints(x):
    c, r = x_to_pack(x)
    b = np.concatenate([c[:,0]-r, 1-(c[:,0]+r), c[:,1]-r, 1-(c[:,1]+r)])
    iu = np.triu_indices(N, 1)
    o = squareform(pdist(c))[iu] - (r[iu[0]] + r[iu[1]])
    return np.concatenate([b, o])

def construct_packing() -> tuple:
    try:
        base_centers = np.loadtxt(os.path.join(BASE_PACKING_PATH, 'centers.txt'))
        base_radii = np.loadtxt(os.path.join(BASE_PACKING_PATH, 'radii.txt'))
    except Exception as e:
        print(f"FATAL: Could not load base packing. {e}")
        return np.random.rand(N, 2), np.full(N, 0.05)

    # --- STAGE 1: NUDGING ---
    print("--- Stage 1: Nudging pair (18,25) ---")
    initial_guess = pack_to_x(base_centers, base_radii)
    bounds = Bounds(np.tile([0,0,1e-6], N), np.tile([1,1,0.5], N))
    ineq_constraints = {'type': 'ineq', 'fun': constraints}

    nudge_result = minimize(
        penalized_objective, initial_guess, method='SLSQP', bounds=bounds,
        constraints=[ineq_constraints], options={'maxiter': 500, 'ftol': 1e-10}
    )

    if not nudge_result.success:
        print("Nudging stage failed. Aborting.")
        return base_centers, base_radii * (1.0 - 1e-7)

    nudged_centers, nudged_radii = x_to_pack(nudge_result.x)
    print(f"Nudging complete. Intermediate score: {np.sum(nudged_radii)}")

    # --- STAGE 2: EXHAUSTIVE REFINEMENT ---
    print("--- Stage 2: Exhaustive Local Refinement ---")
    best_score = np.sum(nudged_radii)
    best_x = nudge_result.x

    for jitter_mag in JITTER_AMPLITUDES:
        for _ in range(RESTARTS_PER_AMPLITUDE):
            perturbed_c = nudged_centers + np.random.uniform(-jitter_mag, jitter_mag, nudged_centers.shape)
            initial_guess_2 = pack_to_x(np.clip(perturbed_c, 0, 1), nudged_radii)

            refine_result = minimize(
                standard_objective, initial_guess_2, method='SLSQP', bounds=bounds,
                constraints=[ineq_constraints], options={'maxiter': 500, 'ftol': 1e-10}
            )

            if refine_result.success:
                current_score = -refine_result.fun
                if current_score > best_score:
                    best_score = current_score
                    best_x = refine_result.x
                    print(f"Refinement found new best score: {best_score}")

    final_centers, final_radii = x_to_pack(best_x)
    return final_centers, final_radii * (1.0 - 1e-7)
